const { useState, useContext, createContext } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const products = ['오버사이즈 셔츠', '니트 베스트', '울 코트'];

// 실무에서는 이 줄이 따로 파일 하나가 됩니다. 여기서는 한 파일에 둡니다.
const CartContext = createContext({ count: 0, add: () => {} });

const Badge = () => {
  const cart = useContext(CartContext);

  return <span className="badge">담은 것 {cart.count}개</span>;
};

const Header = () => (
  <div className="header">
    <h2 className="header__title">JW ANDERSON</h2>
    <Badge />
  </div>
);

const Item = ({ name }) => {
  const cart = useContext(CartContext);

  return (
    <li className="item">
      <span className="item__name">{name}</span>
      <button className="add" type="button" onClick={cart.add}>담기</button>
    </li>
  );
};

const List = () => (
  <ul className="list">
    {products.map((name) => (
      <Item key={name} name={name} />
    ))}
  </ul>
);

const Shop = () => {
  const [count, setCount] = useState(0);

  const cart = { count: count, add: () => setCount((c) => c + 1) };

  return (
    <CartContext.Provider value={cart}>
      <div className="shop">
        <Header />
        <List />
      </div>
    </CartContext.Provider>
  );
};

root.render(<Shop />);

